ALTER TABLE approval_rules DROP CONSTRAINT IF EXISTS approval_rules_operation_type_check;
ALTER TABLE approval_rules ADD CONSTRAINT approval_rules_operation_type_check CHECK(operation_type IN('inventory_adjustment','count_variance','order_cancel','order_reopen','dispatch_reversal','return_reversal','forecast_replenishment','purchase_order_release','item_substitution'));
CREATE UNIQUE INDEX IF NOT EXISTS sales_orders_company_id_id_unique ON sales_orders(company_id,id);
CREATE TABLE order_substitution_approvals (company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,order_id uuid NOT NULL REFERENCES sales_orders(id) ON DELETE CASCADE,relationship_id uuid NOT NULL REFERENCES item_relationships(id) ON DELETE RESTRICT,approval_request_id uuid NOT NULL REFERENCES approval_requests(id) ON DELETE RESTRICT,approved_by uuid REFERENCES users(id),approved_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(order_id,relationship_id),FOREIGN KEY(company_id,order_id) REFERENCES sales_orders(company_id,id));
ALTER TABLE order_substitution_approvals ENABLE ROW LEVEL SECURITY;ALTER TABLE order_substitution_approvals FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_order_substitution_approvals ON order_substitution_approvals USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON order_substitution_approvals TO stockflow_app;
